import fs from 'node:fs';

/**
 * {@link composeSourceMaps} options.
 */
interface ComposeSourceMapsOptions {
  /** Path to React-Native package inside node_modules. */
  reactNativePath: string;

  /**
   * Path to the source map generated by webpack-bundle.
   *
   * This will be replaced with the composed source map.
   */
  packagerMapPath: string;

  /** Path to the source map generated by Hermes. */
  compilerMapPath: string;
}

type SourceMap = Record<string, unknown>;

/**
 * Composes source maps generated by webpack-bundle and Hermes.
 *
 * Does what `react-native/scripts/compose-source-maps.js` does, using the same
 * `metro-source-map` that React Native depends on, but in the current process:
 * starting a Node process for every chunk costs more than composing its maps.
 *
 * Removes original source map files.
 */
export const composeSourceMaps = async ({
  reactNativePath,
  packagerMapPath,
  compilerMapPath,
}: ComposeSourceMapsOptions) => {
  const composedSourceMapPath = packagerMapPath + '.composed';

  try {
    const { composeSourceMaps: compose } = require(
      require.resolve('metro-source-map', { paths: [reactNativePath] })
    ) as { composeSourceMaps: (maps: SourceMap[]) => SourceMap };

    const [packagerMap, compilerMap] = await Promise.all([
      readSourceMap(packagerMapPath),
      readSourceMap(compilerMapPath),
    ]);

    if (
      packagerMap.x_facebook_offsets != null ||
      compilerMap.x_facebook_offsets != null
    ) {
      throw new Error(
        'Random Access Bundle (RAM) format is not supported: ' +
          'cannot process the `x_facebook_offsets` field'
      );
    }

    if (compilerMap.x_facebook_segments != null) {
      throw new Error('Cannot process the `x_facebook_segments` field');
    }

    await fs.promises.writeFile(
      composedSourceMapPath,
      JSON.stringify(compose([packagerMap, compilerMap])),
      'utf8'
    );

    // Remove intermediate files
    await fs.promises.unlink(packagerMapPath);
    await fs.promises.unlink(compilerMapPath);

    await fs.promises.rename(composedSourceMapPath, packagerMapPath);
  } catch (error) {
    const message = (error as Error).toString();
    throw new Error(
      `[RepackHermesBytecodePlugin] Failed to compose source maps. Reason:\n${message})`
    );
  }
};

async function readSourceMap(sourceMapPath: string): Promise<SourceMap> {
  return JSON.parse(await fs.promises.readFile(sourceMapPath, 'utf8'));
}
